define(["jquery"],function($){var captureLocation=function($form){var unsupported=$form.data("location-unsupported");var error=$form.data("location-error");if(!navigator.geolocation){window.alert(unsupported);return}var $button=$form.find("button[type='submit']");$button.prop("disabled",true);navigator.geolocation.getCurrentPosition(function(position){$form.find("input[name='latitude']").val(position.coords.latitude);$form.find("input[name='longitude']").val(position.coords.longitude);$form.find("input[name='accuracy']").val(position.coords.accuracy||"");$form.attr("data-location-ready","1");$form.get(0).submit()},function(){$button.prop("disabled",false);window.alert(error)},{enableHighAccuracy:true,timeout:15e3,maximumAge:0})};return{init:function(){$(document).on("submit","form[data-checkin-location-form='1']",function(event){var $form=$(this);if($form.attr("data-location-ready")==="1"){return}event.preventDefault();captureLocation($form)});$(document).on("submit","form[data-checkin-student-form='1']",function(event){var $form=$(this);if($form.data("require-location")!==1||$form.attr("data-location-ready")==="1"){return}event.preventDefault();captureLocation($form)})}}});